export type ParsedBoostBuyAndBurnInstruction<
  TProgram extends string = typeof PUMP_AMM_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    pool: TAccountMetas[0];
    authority: TAccountMetas[1];
    globalConfig: TAccountMetas[2];
    baseMint: TAccountMetas[3];
    quoteMint: TAccountMetas[4];
    poolBaseTokenAccount: TAccountMetas[5];
    poolQuoteTokenAccount: TAccountMetas[6];
    boostVaultAuthority: TAccountMetas[7];
    boostVault: TAccountMetas[8];
    baseTokenProgram: TAccountMetas[9];
    quoteTokenProgram: TAccountMetas[10];
    eventAuthority: TAccountMetas[11];
    program: TAccountMetas[12];
  };
  data: BoostBuyAndBurnInstructionData;
};

export function parseBoostBuyAndBurnInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedBoostBuyAndBurnInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 13) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 13,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      pool: getNextAccount(),
      authority: getNextAccount(),
      globalConfig: getNextAccount(),
      baseMint: getNextAccount(),
      quoteMint: getNextAccount(),
      poolBaseTokenAccount: getNextAccount(),
      poolQuoteTokenAccount: getNextAccount(),
      boostVaultAuthority: getNextAccount(),
      boostVault: getNextAccount(),
      baseTokenProgram: getNextAccount(),
      quoteTokenProgram: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getBoostBuyAndBurnInstructionDataDecoder().decode(instruction.data),
  };
}
